def localizedIntegralPart (T : Lp ℝ 1 μ →L[ℝ] Lp ℝ 1 ν) :
    Lp ℝ 1 μ →L[ℝ] Lp ℝ 1 (ν.restrict Θ) :=
  integralBandProjection ((lebesgueLpRestrict (𝕜 := ℝ) Θ).comp T)

