def localizedIntegralRemainder (hΘ : MeasurableSet Θ)
    (T : Lp ℝ 1 μ →L[ℝ] Lp ℝ 1 ν) : Lp ℝ 1 μ →L[ℝ] Lp ℝ 1 ν :=
  T - (lebesgueLpExtend (𝕜 := ℝ) Θ hΘ).toContinuousLinearMap.comp (localizedIntegralPart Θ T)

